values (
  'en-human-digestive-system-trivia',
  'Human Digestive System Trivia: From Mouth to Gut',
  'Eight questions on how your body digests food: the organs, enzymes and the journey from the first bite to nutrient absorption.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Which organ produces the bile that helps digest fats?","options":[{"id":"a","text":"The pancreas","is_correct":false},{"id":"b","text":"The liver","is_correct":true},{"id":"c","text":"The gallbladder","is_correct":false},{"id":"d","text":"The stomach","is_correct":false}],"explanation":"The liver produces bile continuously; the gallbladder only stores and concentrates it."},{"id":"q2","question":"Where does most nutrient absorption take place?","options":[{"id":"a","text":"The stomach","is_correct":false},{"id":"b","text":"The large intestine","is_correct":false},{"id":"c","text":"The small intestine","is_correct":true},{"id":"d","text":"The esophagus","is_correct":false}],"explanation":"The small intestine''s villi and microvilli give it a huge surface area to absorb nutrients."},{"id":"q3","question":"About how long is an adult''s small intestine?","options":[{"id":"a","text":"About 1 metre","is_correct":false},{"id":"b","text":"About 3 metres","is_correct":false},{"id":"c","text":"About 6 metres","is_correct":true},{"id":"d","text":"About 12 metres","is_correct":false}],"explanation":"Despite its name, the small intestine measures roughly 6 metres, far longer than the 1.5-metre large intestine."},{"id":"q4","question":"Which enzyme in saliva begins breaking down starch?","options":[{"id":"a","text":"Amylase","is_correct":true},{"id":"b","text":"Pepsin","is_correct":false},{"id":"c","text":"Lipase","is_correct":false},{"id":"d","text":"Trypsin","is_correct":false}],"explanation":"Salivary amylase starts digesting starch in the mouth, before food even reaches the stomach."},{"id":"q5","question":"What does the large intestine mainly absorb?","options":[{"id":"a","text":"Proteins","is_correct":false},{"id":"b","text":"Water and electrolytes","is_correct":true},{"id":"c","text":"Sugars","is_correct":false},{"id":"d","text":"Fats","is_correct":false}],"explanation":"The colon absorbs water and salts from the leftover material, turning it into solid waste."},{"id":"q6","question":"What is the wave-like muscle movement that pushes food through the digestive tract?","options":[{"id":"a","text":"Segmentation","is_correct":false},{"id":"b","text":"Osmosis","is_correct":false},{"id":"c","text":"Reflux","is_correct":false},{"id":"d","text":"Peristalsis","is_correct":true}],"explanation":"Peristalsis is the coordinated contraction of the tract''s muscles that moves food along."},{"id":"q7","question":"Where does protein digestion begin, driven by the enzyme pepsin?","options":[{"id":"a","text":"The mouth","is_correct":false},{"id":"b","text":"The stomach","is_correct":true},{"id":"c","text":"The small intestine","is_correct":false},{"id":"d","text":"The large intestine","is_correct":false}],"explanation":"Pepsin and hydrochloric acid start breaking proteins down in the stomach."},{"id":"q8","question":"Which organ stores bile until it is needed for digestion?","options":[{"id":"a","text":"The gallbladder","is_correct":true},{"id":"b","text":"The liver","is_correct":false},{"id":"c","text":"The appendix","is_correct":false},{"id":"d","text":"The spleen","is_correct":false}],"explanation":"The gallbladder concentrates bile and releases it into the small intestine after fatty meals."}]'::jsonb,
  null,
  array['science', 'human body', 'digestion', 'anatomy']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
