values (
  'es-trivia-sistema-digestivo',
  'Trivia del sistema digestivo: de la boca al intestino',
  'Ocho preguntas sobre cómo digiere tu cuerpo: los órganos, las enzimas y el recorrido de los alimentos hasta su absorción.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué órgano produce la bilis que ayuda a digerir las grasas?","options":[{"id":"a","text":"El páncreas","is_correct":false},{"id":"b","text":"El hígado","is_correct":true},{"id":"c","text":"La vesícula biliar","is_correct":false},{"id":"d","text":"El estómago","is_correct":false}],"explanation":"El hígado produce bilis de forma continua; la vesícula biliar solo la almacena y la concentra."},{"id":"q2","question":"¿Dónde se absorbe la mayoría de los nutrientes?","options":[{"id":"a","text":"El estómago","is_correct":false},{"id":"b","text":"El intestino grueso","is_correct":false},{"id":"c","text":"El intestino delgado","is_correct":true},{"id":"d","text":"El esófago","is_correct":false}],"explanation":"Las vellosidades del intestino delgado le dan una superficie enorme para absorber nutrientes."},{"id":"q3","question":"¿Cuánto mide aproximadamente el intestino delgado de un adulto?","options":[{"id":"a","text":"Aproximadamente 1 metro","is_correct":false},{"id":"b","text":"Aproximadamente 3 metros","is_correct":false},{"id":"c","text":"Aproximadamente 6 metros","is_correct":true},{"id":"d","text":"Aproximadamente 12 metros","is_correct":false}],"explanation":"A pesar de su nombre, el intestino delgado mide unos 6 metros, mucho más que el grueso, que ronda 1,5 metros."},{"id":"q4","question":"¿Qué enzima de la saliva empieza a descomponer el almidón?","options":[{"id":"a","text":"La amilasa","is_correct":true},{"id":"b","text":"La pepsina","is_correct":false},{"id":"c","text":"La lipasa","is_correct":false},{"id":"d","text":"La tripsina","is_correct":false}],"explanation":"La amilasa salival comienza a digerir el almidón en la boca, antes de que la comida llegue al estómago."},{"id":"q5","question":"¿Qué absorbe principalmente el intestino grueso?","options":[{"id":"a","text":"Proteínas","is_correct":false},{"id":"b","text":"Agua y electrolitos","is_correct":true},{"id":"c","text":"Azúcares","is_correct":false},{"id":"d","text":"Grasas","is_correct":false}],"explanation":"El colon absorbe agua y sales del material restante y lo convierte en residuos sólidos."},{"id":"q6","question":"¿Cómo se llama el movimiento muscular en forma de ola que empuja los alimentos por el tracto digestivo?","options":[{"id":"a","text":"La segmentación","is_correct":false},{"id":"b","text":"La ósmosis","is_correct":false},{"id":"c","text":"El reflujo","is_correct":false},{"id":"d","text":"La peristalsis","is_correct":true}],"explanation":"La peristalsis es la contracción coordinada de los músculos del tracto que hace avanzar los alimentos."},{"id":"q7","question":"¿Dónde comienza la digestión de las proteínas, impulsada por la enzima pepsina?","options":[{"id":"a","text":"La boca","is_correct":false},{"id":"b","text":"El estómago","is_correct":true},{"id":"c","text":"El intestino delgado","is_correct":false},{"id":"d","text":"El intestino grueso","is_correct":false}],"explanation":"La pepsina y el ácido clorhídrico empiezan a descomponer las proteínas en el estómago."},{"id":"q8","question":"¿Qué órgano almacena la bilis hasta que se necesita para la digestión?","options":[{"id":"a","text":"La vesícula biliar","is_correct":true},{"id":"b","text":"El hígado","is_correct":false},{"id":"c","text":"El apéndice","is_correct":false},{"id":"d","text":"El bazo","is_correct":false}],"explanation":"La vesícula biliar concentra la bilis y la libera en el intestino delgado tras las comidas grasas."}]'::jsonb,
  null,
  array['ciencia', 'cuerpo humano', 'digestión', 'anatomía']::text[],
  3,
  'published',
  false,
  false,
  now()
)
