insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-heart-and-circulation-trivia',
  'Heart and Circulation Trivia: How Your Blood Flows',
  'Eight questions on the heart, arteries, veins and blood cells that keep your circulation running every second.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"How many chambers does the human heart have?","options":[{"id":"a","text":"Two","is_correct":false},{"id":"b","text":"Three","is_correct":false},{"id":"c","text":"Four","is_correct":true},{"id":"d","text":"Six","is_correct":false}],"explanation":"The heart has two atria on top and two ventricles below: four chambers in total."},{"id":"q2","question":"Which is the largest artery in the human body?","options":[{"id":"a","text":"The aorta","is_correct":true},{"id":"b","text":"The carotid artery","is_correct":false},{"id":"c","text":"The pulmonary artery","is_correct":false},{"id":"d","text":"The femoral artery","is_correct":false}],"explanation":"The aorta carries oxygen-rich blood out of the left ventricle to the whole body."},{"id":"q3","question":"Which blood cells carry oxygen around the body?","options":[{"id":"a","text":"White blood cells","is_correct":false},{"id":"b","text":"Platelets","is_correct":false},{"id":"c","text":"Plasma cells","is_correct":false},{"id":"d","text":"Red blood cells","is_correct":true}],"explanation":"Haemoglobin inside red blood cells binds oxygen in the lungs and releases it to the tissues."},{"id":"q4","question":"Which vessels carry blood back to the heart?","options":[{"id":"a","text":"Arteries","is_correct":false},{"id":"b","text":"Veins","is_correct":true},{"id":"c","text":"Capillaries","is_correct":false},{"id":"d","text":"Arterioles","is_correct":false}],"explanation":"Veins return blood to the heart; arteries carry it away from it."},{"id":"q5","question":"Where does the exchange of oxygen and carbon dioxide take place?","options":[{"id":"a","text":"In the capillaries","is_correct":true},{"id":"b","text":"In the arteries","is_correct":false},{"id":"c","text":"In the veins","is_correct":false},{"id":"d","text":"In the heart valves","is_correct":false}],"explanation":"Capillary walls are one cell thick, letting gases pass between the blood and the tissues or the lungs'' alveoli."},{"id":"q6","question":"What is a typical resting heart rate for an adult?","options":[{"id":"a","text":"30 to 40 beats per minute","is_correct":false},{"id":"b","text":"60 to 100 beats per minute","is_correct":true},{"id":"c","text":"120 to 140 beats per minute","is_correct":false},{"id":"d","text":"160 to 180 beats per minute","is_correct":false}],"explanation":"A normal resting adult heart rate is 60-100 beats per minute, often lower in trained athletes."},{"id":"q7","question":"Which chamber pumps oxygenated blood to the entire body?","options":[{"id":"a","text":"The right atrium","is_correct":false},{"id":"b","text":"The right ventricle","is_correct":false},{"id":"c","text":"The left atrium","is_correct":false},{"id":"d","text":"The left ventricle","is_correct":true}],"explanation":"The left ventricle has the thickest wall because it pushes blood into the aorta for the whole body."},{"id":"q8","question":"What do platelets do?","options":[{"id":"a","text":"Carry oxygen","is_correct":false},{"id":"b","text":"Fight infections","is_correct":false},{"id":"c","text":"Help blood clot","is_correct":true},{"id":"d","text":"Carry hormones","is_correct":false}],"explanation":"Platelets gather at a wound and trigger clotting to stop the bleeding."}]'::jsonb,
  null,
  array['science', 'human body', 'heart', 'anatomy']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
