values (
  'es-trivia-corazon-y-circulacion',
  'Trivia del corazón y la circulación: cómo fluye tu sangre',
  'Ocho preguntas sobre el corazón, las arterias, las venas y las células de la sangre que mantienen tu circulación.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuántas cavidades tiene el corazón humano?","options":[{"id":"a","text":"Dos","is_correct":false},{"id":"b","text":"Tres","is_correct":false},{"id":"c","text":"Cuatro","is_correct":true},{"id":"d","text":"Seis","is_correct":false}],"explanation":"El corazón tiene dos aurículas arriba y dos ventrículos abajo: cuatro cavidades en total."},{"id":"q2","question":"¿Cuál es la arteria más grande del cuerpo humano?","options":[{"id":"a","text":"La aorta","is_correct":true},{"id":"b","text":"La carótida","is_correct":false},{"id":"c","text":"La arteria pulmonar","is_correct":false},{"id":"d","text":"La arteria femoral","is_correct":false}],"explanation":"La aorta saca la sangre rica en oxígeno del ventrículo izquierdo hacia todo el cuerpo."},{"id":"q3","question":"¿Qué células de la sangre transportan el oxígeno por el cuerpo?","options":[{"id":"a","text":"Los glóbulos blancos","is_correct":false},{"id":"b","text":"Las plaquetas","is_correct":false},{"id":"c","text":"Las células plasmáticas","is_correct":false},{"id":"d","text":"Los glóbulos rojos","is_correct":true}],"explanation":"La hemoglobina de los glóbulos rojos captura el oxígeno en los pulmones y lo entrega a los tejidos."},{"id":"q4","question":"¿Qué vasos llevan la sangre de vuelta al corazón?","options":[{"id":"a","text":"Las arterias","is_correct":false},{"id":"b","text":"Las venas","is_correct":true},{"id":"c","text":"Los capilares","is_correct":false},{"id":"d","text":"Las arteriolas","is_correct":false}],"explanation":"Las venas devuelven la sangre al corazón; las arterias la sacan de él."},{"id":"q5","question":"¿Dónde ocurre el intercambio de oxígeno y dióxido de carbono?","options":[{"id":"a","text":"En los capilares","is_correct":true},{"id":"b","text":"En las arterias","is_correct":false},{"id":"c","text":"En las venas","is_correct":false},{"id":"d","text":"En las válvulas del corazón","is_correct":false}],"explanation":"Las paredes de los capilares tienen una célula de grosor y dejan pasar los gases entre la sangre y los tejidos o los alvéolos."},{"id":"q6","question":"¿Cuál es la frecuencia cardíaca típica de un adulto en reposo?","options":[{"id":"a","text":"De 30 a 40 latidos por minuto","is_correct":false},{"id":"b","text":"De 60 a 100 latidos por minuto","is_correct":true},{"id":"c","text":"De 120 a 140 latidos por minuto","is_correct":false},{"id":"d","text":"De 160 a 180 latidos por minuto","is_correct":false}],"explanation":"La frecuencia normal en reposo es de 60 a 100 latidos por minuto, y suele ser menor en deportistas entrenados."},{"id":"q7","question":"¿Qué cavidad bombea la sangre oxigenada hacia todo el cuerpo?","options":[{"id":"a","text":"La aurícula derecha","is_correct":false},{"id":"b","text":"El ventrículo derecho","is_correct":false},{"id":"c","text":"La aurícula izquierda","is_correct":false},{"id":"d","text":"El ventrículo izquierdo","is_correct":true}],"explanation":"El ventrículo izquierdo tiene la pared más gruesa porque empuja la sangre hacia la aorta para todo el cuerpo."},{"id":"q8","question":"¿Qué hacen las plaquetas?","options":[{"id":"a","text":"Transportan oxígeno","is_correct":false},{"id":"b","text":"Combaten infecciones","is_correct":false},{"id":"c","text":"Ayudan a coagular la sangre","is_correct":true},{"id":"d","text":"Transportan hormonas","is_correct":false}],"explanation":"Las plaquetas se acumulan en una herida y activan la coagulación para detener el sangrado."}]'::jsonb,
  null,
  array['ciencia', 'cuerpo humano', 'corazón', 'anatomía']::text[],
  3,
  'published',
  false,
  false,
  now()
)
