insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-bones-and-muscles-trivia',
  'Bones and Muscles Trivia: The Body''s Framework',
  'Eight questions on the human skeleton and muscles: the longest bone, the smallest one and the tissues that move you.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"How many bones does an adult human skeleton have?","options":[{"id":"a","text":"106","is_correct":false},{"id":"b","text":"206","is_correct":true},{"id":"c","text":"306","is_correct":false},{"id":"d","text":"406","is_correct":false}],"explanation":"Babies are born with around 300 bones that fuse into 206 by adulthood."},{"id":"q2","question":"What is the longest bone in the human body?","options":[{"id":"a","text":"The tibia","is_correct":false},{"id":"b","text":"The humerus","is_correct":false},{"id":"c","text":"The femur","is_correct":true},{"id":"d","text":"The fibula","is_correct":false}],"explanation":"The femur, or thigh bone, is the longest and strongest bone in the skeleton."},{"id":"q3","question":"What is the smallest bone in the human body?","options":[{"id":"a","text":"The kneecap","is_correct":false},{"id":"b","text":"The coccyx","is_correct":false},{"id":"c","text":"A finger bone","is_correct":false},{"id":"d","text":"The stapes","is_correct":true}],"explanation":"The stapes, one of the three middle-ear ossicles, is barely 3 millimetres long."},{"id":"q4","question":"What is the largest muscle in the human body?","options":[{"id":"a","text":"The biceps","is_correct":false},{"id":"b","text":"The gluteus maximus","is_correct":true},{"id":"c","text":"The masseter","is_correct":false},{"id":"d","text":"The trapezius","is_correct":false}],"explanation":"The gluteus maximus is the body''s largest muscle; it powers standing up, climbing and running."},{"id":"q5","question":"Where in the body is the patella located?","options":[{"id":"a","text":"The elbow","is_correct":false},{"id":"b","text":"The shoulder","is_correct":false},{"id":"c","text":"The knee","is_correct":true},{"id":"d","text":"The wrist","is_correct":false}],"explanation":"The patella is the kneecap, a sesamoid bone that protects the knee joint."},{"id":"q6","question":"Which tissue connects muscle to bone?","options":[{"id":"a","text":"Tendons","is_correct":true},{"id":"b","text":"Ligaments","is_correct":false},{"id":"c","text":"Cartilage","is_correct":false},{"id":"d","text":"Nerves","is_correct":false}],"explanation":"Tendons attach muscles to bones, while ligaments connect bones to other bones."},{"id":"q7","question":"What type of muscle makes up the heart?","options":[{"id":"a","text":"Skeletal muscle","is_correct":false},{"id":"b","text":"Smooth muscle","is_correct":false},{"id":"c","text":"Cardiac muscle","is_correct":true},{"id":"d","text":"Voluntary muscle","is_correct":false}],"explanation":"Cardiac muscle is involuntary and contracts rhythmically without tiring for a lifetime."},{"id":"q8","question":"What does red bone marrow produce?","options":[{"id":"a","text":"Hormones","is_correct":false},{"id":"b","text":"Blood cells","is_correct":true},{"id":"c","text":"Calcium","is_correct":false},{"id":"d","text":"Synovial fluid","is_correct":false}],"explanation":"Red marrow makes red and white blood cells and platelets, mostly inside flat bones like the pelvis."}]'::jsonb,
  null,
  array['science', 'human body', 'bones', 'muscles']::text[],
  3,
  'published',
  false,
  false,
  now()
)
