insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-huesos-y-musculos',
  'Trivia de huesos y músculos: la estructura de tu cuerpo',
  'Ocho preguntas sobre el esqueleto y los músculos humanos: el hueso más largo, el más pequeño y los tejidos que te mueven.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuántos huesos tiene el esqueleto de un adulto?","options":[{"id":"a","text":"106","is_correct":false},{"id":"b","text":"206","is_correct":true},{"id":"c","text":"306","is_correct":false},{"id":"d","text":"406","is_correct":false}],"explanation":"Los bebés nacen con unos 300 huesos que se fusionan hasta los 206 en la adultez."},{"id":"q2","question":"¿Cuál es el hueso más largo del cuerpo humano?","options":[{"id":"a","text":"La tibia","is_correct":false},{"id":"b","text":"El húmero","is_correct":false},{"id":"c","text":"El fémur","is_correct":true},{"id":"d","text":"El peroné","is_correct":false}],"explanation":"El fémur, el hueso del muslo, es el más largo y el más resistente del esqueleto."},{"id":"q3","question":"¿Cuál es el hueso más pequeño del cuerpo humano?","options":[{"id":"a","text":"La rótula","is_correct":false},{"id":"b","text":"El cóccix","is_correct":false},{"id":"c","text":"Un hueso de los dedos","is_correct":false},{"id":"d","text":"El estribo","is_correct":true}],"explanation":"El estribo, uno de los tres huesecillos del oído medio, mide apenas 3 milímetros."},{"id":"q4","question":"¿Cuál es el músculo más grande del cuerpo humano?","options":[{"id":"a","text":"El bíceps","is_correct":false},{"id":"b","text":"El glúteo mayor","is_correct":true},{"id":"c","text":"El masetero","is_correct":false},{"id":"d","text":"El trapecio","is_correct":false}],"explanation":"El glúteo mayor es el músculo más grande del cuerpo; impulsa al ponerte de pie, subir escaleras y correr."},{"id":"q5","question":"¿Dónde está la rótula?","options":[{"id":"a","text":"El codo","is_correct":false},{"id":"b","text":"El hombro","is_correct":false},{"id":"c","text":"La rodilla","is_correct":true},{"id":"d","text":"La muñeca","is_correct":false}],"explanation":"La rótula es el hueso que protege la articulación de la rodilla."},{"id":"q6","question":"¿Qué tejido une los músculos con los huesos?","options":[{"id":"a","text":"Los tendones","is_correct":true},{"id":"b","text":"Los ligamentos","is_correct":false},{"id":"c","text":"El cartílago","is_correct":false},{"id":"d","text":"Los nervios","is_correct":false}],"explanation":"Los tendones unen músculos a huesos; los ligamentos conectan unos huesos con otros."},{"id":"q7","question":"¿Qué tipo de músculo forma el corazón?","options":[{"id":"a","text":"El músculo esquelético","is_correct":false},{"id":"b","text":"El músculo liso","is_correct":false},{"id":"c","text":"El músculo cardíaco","is_correct":true},{"id":"d","text":"El músculo voluntario","is_correct":false}],"explanation":"El músculo cardíaco es involuntario y se contrae de forma rítmica sin cansarse durante toda la vida."},{"id":"q8","question":"¿Qué produce la médula ósea roja?","options":[{"id":"a","text":"Hormonas","is_correct":false},{"id":"b","text":"Células de la sangre","is_correct":true},{"id":"c","text":"Calcio","is_correct":false},{"id":"d","text":"Líquido sinovial","is_correct":false}],"explanation":"La médula roja fabrica glóbulos rojos, glóbulos blancos y plaquetas, sobre todo en huesos planos como la pelvis."}]'::jsonb,
  null,
  array['ciencia', 'cuerpo humano', 'huesos', 'músculos']::text[],
  3,
  'published',
