insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-human-brain-trivia',
  'Human Brain Trivia: Neurons and the Control Center',
  'Eight questions on the brain and nervous system: neurons, the cerebellum, cranial nerves and the signals that run you.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Roughly how many neurons does the human brain contain?","options":[{"id":"a","text":"About 86 million","is_correct":false},{"id":"b","text":"About 860 million","is_correct":false},{"id":"c","text":"About 8.6 billion","is_correct":false},{"id":"d","text":"About 86 billion","is_correct":true}],"explanation":"The accepted estimate is about 86 billion neurons, plus a similar number of glial cells."},{"id":"q2","question":"Which part of the brain controls balance and coordination?","options":[{"id":"a","text":"The cerebrum","is_correct":false},{"id":"b","text":"The cerebellum","is_correct":true},{"id":"c","text":"The hypothalamus","is_correct":false},{"id":"d","text":"The brainstem","is_correct":false}],"explanation":"The cerebellum, at the back of the skull, fine-tunes movement, posture and balance."},{"id":"q3","question":"Which is the largest part of the human brain?","options":[{"id":"a","text":"The cerebellum","is_correct":false},{"id":"b","text":"The brainstem","is_correct":false},{"id":"c","text":"The cerebrum","is_correct":true},{"id":"d","text":"The thalamus","is_correct":false}],"explanation":"The cerebrum makes up about 85% of the brain''s mass and handles thought, senses and voluntary movement."},{"id":"q4","question":"Which cells transmit electrical signals through the nervous system?","options":[{"id":"a","text":"Neurons","is_correct":true},{"id":"b","text":"Glial cells","is_correct":false},{"id":"c","text":"Stem cells","is_correct":false},{"id":"d","text":"Red blood cells","is_correct":false}],"explanation":"Neurons fire electrochemical impulses; glial cells support and insulate them."},{"id":"q5","question":"What is the longest nerve in the human body?","options":[{"id":"a","text":"The optic nerve","is_correct":false},{"id":"b","text":"The vagus nerve","is_correct":false},{"id":"c","text":"The femoral nerve","is_correct":false},{"id":"d","text":"The sciatic nerve","is_correct":true}],"explanation":"The sciatic nerve runs from the lower back down each leg to the foot."},{"id":"q6","question":"Which small brain region regulates hunger, thirst and body temperature?","options":[{"id":"a","text":"The amygdala","is_correct":false},{"id":"b","text":"The hypothalamus","is_correct":true},{"id":"c","text":"The hippocampus","is_correct":false},{"id":"d","text":"The medulla oblongata","is_correct":false}],"explanation":"The hypothalamus keeps the body''s internal balance and links the nervous and endocrine systems."},{"id":"q7","question":"Which structure carries signals between the brain and the rest of the body?","options":[{"id":"a","text":"The spinal cord","is_correct":true},{"id":"b","text":"The vagus nerve","is_correct":false},{"id":"c","text":"The carotid artery","is_correct":false},{"id":"d","text":"The cerebellum","is_correct":false}],"explanation":"The spinal cord runs inside the vertebral column and relays messages between brain and body."},{"id":"q8","question":"How many pairs of cranial nerves does the human body have?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"10","is_correct":false},{"id":"c","text":"12","is_correct":true},{"id":"d","text":"31","is_correct":false}],"explanation":"Twelve pairs of cranial nerves leave the brain; the 31 pairs of spinal nerves branch from the spinal cord."}]'::jsonb,
  null,
  array['science', 'human body', 'brain', 'nervous system']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-cerebro',
  'Trivia del cerebro humano: neuronas y el centro de control',
  'Ocho preguntas sobre el cerebro y el sistema nervioso: neuronas, cerebelo, nervios craneales y las señales que te controlan.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuántas neuronas tiene aproximadamente el cerebro humano?","options":[{"id":"a","text":"Unos 86 millones","is_correct":false},{"id":"b","text":"Unos 860 millones","is_correct":false},{"id":"c","text":"Unos 8.600 millones","is_correct":false},{"id":"d","text":"Unos 86.000 millones","is_correct":true}],"explanation":"La estimación aceptada es de unos 86.000 millones de neuronas, más una cifra parecida de células gliales."},{"id":"q2","question":"¿Qué parte del cerebro controla el equilibrio y la coordinación?","options":[{"id":"a","text":"El cerebro","is_correct":false},{"id":"b","text":"El cerebelo","is_correct":true},{"id":"c","text":"El hipotálamo","is_correct":false},{"id":"d","text":"El tronco encefálico","is_correct":false}],"explanation":"El cerebelo, en la parte posterior del cráneo, ajusta el movimiento, la postura y el equilibrio."},{"id":"q3","question":"¿Cuál es la parte más grande del cerebro humano?","options":[{"id":"a","text":"El cerebelo","is_correct":false},{"id":"b","text":"El tronco encefálico","is_correct":false},{"id":"c","text":"El cerebro","is_correct":true},{"id":"d","text":"El tálamo","is_correct":false}],"explanation":"El cerebro supone alrededor del 85 % de la masa encefálica y se encarga del pensamiento, los sentidos y el movimiento voluntario."},{"id":"q4","question":"¿Qué células transmiten señales eléctricas por el sistema nervioso?","options":[{"id":"a","text":"Las neuronas","is_correct":true},{"id":"b","text":"Las células gliales","is_correct":false},{"id":"c","text":"Las células madre","is_correct":false},{"id":"d","text":"Los glóbulos rojos","is_correct":false}],"explanation":"Las neuronas emiten impulsos electroquímicos; las células gliales las sostienen y las aíslan."},{"id":"q5","question":"¿Cuál es el nervio más largo del cuerpo humano?","options":[{"id":"a","text":"El nervio óptico","is_correct":false},{"id":"b","text":"El nervio vago","is_correct":false},{"id":"c","text":"El nervio femoral","is_correct":false},{"id":"d","text":"El nervio ciático","is_correct":true}],"explanation":"El nervio ciático recorre la pierna desde la parte baja de la espalda hasta el pie."},{"id":"q6","question":"¿Qué pequeña región del cerebro regula el hambre, la sed y la temperatura corporal?","options":[{"id":"a","text":"La amígdala","is_correct":false},{"id":"b","text":"El hipotálamo","is_correct":true},{"id":"c","text":"El hipocampo","is_correct":false},{"id":"d","text":"El bulbo raquídeo","is_correct":false}],"explanation":"El hipotálamo mantiene el equilibrio interno del cuerpo y conecta los sistemas nervioso y endocrino."},{"id":"q7","question":"¿Qué estructura lleva las señales entre el cerebro y el resto del cuerpo?","options":[{"id":"a","text":"La médula espinal","is_correct":true},{"id":"b","text":"El nervio vago","is_correct":false},{"id":"c","text":"La arteria carótida","is_correct":false},{"id":"d","text":"El cerebelo","is_correct":false}],"explanation":"La médula espinal recorre el interior de la columna vertebral y transmite mensajes entre el cerebro y el cuerpo."},{"id":"q8","question":"¿Cuántos pares de nervios craneales tiene el cuerpo humano?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"10","is_correct":false},{"id":"c","text":"12","is_correct":true},{"id":"d","text":"31","is_correct":false}],"explanation":"Doce pares de nervios craneales salen del cerebro; los 31 pares de nervios espinales parten de la médula espinal."}]'::jsonb,
  null,
  array['ciencia', 'cuerpo humano', 'cerebro', 'sistema nervioso']::text[],
  3,
  'published',
  false,
  false,
  now()
)
