insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-immune-system-trivia',
  'Immune System Trivia: Defenses, Antibodies and Vaccines',
  'Eight questions on how your body fights infection: white blood cells, antibodies, lymph nodes and the power of vaccines.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the body''s first line of defense against pathogens?","options":[{"id":"a","text":"Antibodies","is_correct":false},{"id":"b","text":"The skin","is_correct":true},{"id":"c","text":"White blood cells","is_correct":false},{"id":"d","text":"Lymph nodes","is_correct":false}],"explanation":"Skin and mucous membranes are physical barriers that block most invaders before they get in."},{"id":"q2","question":"Which blood cells defend the body against infection?","options":[{"id":"a","text":"Red blood cells","is_correct":false},{"id":"b","text":"Platelets","is_correct":false},{"id":"c","text":"White blood cells","is_correct":true},{"id":"d","text":"Stem cells","is_correct":false}],"explanation":"Leukocytes — white blood cells — hunt down and destroy invading microbes."},{"id":"q3","question":"What do antibodies recognise on a pathogen?","options":[{"id":"a","text":"Antigens","is_correct":true},{"id":"b","text":"Hormones","is_correct":false},{"id":"c","text":"Platelets","is_correct":false},{"id":"d","text":"Enzymes","is_correct":false}],"explanation":"Each antibody fits a specific antigen on the surface of a bacterium or virus."},{"id":"q4","question":"Where do T lymphocytes mature?","options":[{"id":"a","text":"The bone marrow","is_correct":false},{"id":"b","text":"The spleen","is_correct":false},{"id":"c","text":"The lymph nodes","is_correct":false},{"id":"d","text":"The thymus","is_correct":true}],"explanation":"The ''T'' in T cell stands for thymus, the gland where they finish their training."},{"id":"q5","question":"What does a vaccine give the immune system?","options":[{"id":"a","text":"A full-strength infection","is_correct":false},{"id":"b","text":"Antibiotics","is_correct":false},{"id":"c","text":"A harmless version or fragment of the pathogen","is_correct":true},{"id":"d","text":"Donated blood cells","is_correct":false}],"explanation":"Vaccines expose the immune system to a weakened, killed or partial pathogen so it builds memory without the disease."},{"id":"q6","question":"Who developed the first successful smallpox vaccine?","options":[{"id":"a","text":"Louis Pasteur","is_correct":false},{"id":"b","text":"Alexander Fleming","is_correct":false},{"id":"c","text":"Robert Koch","is_correct":false},{"id":"d","text":"Edward Jenner","is_correct":true}],"explanation":"In 1796 Jenner used cowpox material to protect against smallpox; ''vaccine'' comes from vacca, Latin for cow."},{"id":"q7","question":"Which structures filter lymph and trap pathogens?","options":[{"id":"a","text":"The kidneys","is_correct":false},{"id":"b","text":"The lymph nodes","is_correct":true},{"id":"c","text":"The alveoli","is_correct":false},{"id":"d","text":"The adrenal glands","is_correct":false}],"explanation":"Lymph nodes are checkpoints packed with immune cells that scan lymph for invaders."},{"id":"q8","question":"Which was the first human disease eradicated worldwide thanks to vaccination?","options":[{"id":"a","text":"Smallpox","is_correct":true},{"id":"b","text":"Polio","is_correct":false},{"id":"c","text":"Measles","is_correct":false},{"id":"d","text":"Tuberculosis","is_correct":false}],"explanation":"The WHO declared smallpox eradicated in 1980, after a global vaccination campaign."}]'::jsonb,
  null,
  array['science', 'human body', 'immune system', 'vaccines', 'health']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-sistema-inmune',
  'Trivia del sistema inmune: defensas, anticuerpos y vacunas',
  'Ocho preguntas sobre cómo te defiende tu cuerpo: glóbulos blancos, anticuerpos, ganglios linfáticos y el poder de las vacunas.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuál es la primera línea de defensa del cuerpo contra los patógenos?","options":[{"id":"a","text":"Los anticuerpos","is_correct":false},{"id":"b","text":"La piel","is_correct":true},{"id":"c","text":"Los glóbulos blancos","is_correct":false},{"id":"d","text":"Los ganglios linfáticos","is_correct":false}],"explanation":"La piel y las mucosas son barreras físicas que bloquean a la mayoría de los invasores antes de que entren."},{"id":"q2","question":"¿Qué células de la sangre defienden el cuerpo de las infecciones?","options":[{"id":"a","text":"Los glóbulos rojos","is_correct":false},{"id":"b","text":"Las plaquetas","is_correct":false},{"id":"c","text":"Los glóbulos blancos","is_correct":true},{"id":"d","text":"Las células madre","is_correct":false}],"explanation":"Los leucocitos, o glóbulos blancos, persiguen y destruyen los microbios invasores."},{"id":"q3","question":"¿Qué reconocen los anticuerpos en un patógeno?","options":[{"id":"a","text":"Los antígenos","is_correct":true},{"id":"b","text":"Las hormonas","is_correct":false},{"id":"c","text":"Las plaquetas","is_correct":false},{"id":"d","text":"Las enzimas","is_correct":false}],"explanation":"Cada anticuerpo encaja con un antígeno específico de la superficie de una bacteria o un virus."},{"id":"q4","question":"¿Dónde maduran los linfocitos T?","options":[{"id":"a","text":"La médula ósea","is_correct":false},{"id":"b","text":"El bazo","is_correct":false},{"id":"c","text":"Los ganglios linfáticos","is_correct":false},{"id":"d","text":"El timo","is_correct":true}],"explanation":"La «T» de linfocito T viene de timo, la glándula donde completan su formación."},{"id":"q5","question":"¿Qué le proporciona una vacuna al sistema inmune?","options":[{"id":"a","text":"Una infección a máxima potencia","is_correct":false},{"id":"b","text":"Antibióticos","is_correct":false},{"id":"c","text":"Una versión o fragmento inofensivo del patógeno","is_correct":true},{"id":"d","text":"Células de sangre donada","is_correct":false}],"explanation":"Las vacunas exponen al sistema inmune a un patógeno debilitado, inactivado o parcial para que cree memoria sin pasar la enfermedad."},{"id":"q6","question":"¿Quién desarrolló la primera vacuna exitosa contra la viruela?","options":[{"id":"a","text":"Louis Pasteur","is_correct":false},{"id":"b","text":"Alexander Fleming","is_correct":false},{"id":"c","text":"Robert Koch","is_correct":false},{"id":"d","text":"Edward Jenner","is_correct":true}],"explanation":"En 1796, Jenner usó material de la viruela bovina para proteger de la viruela; la palabra «vacuna» viene de vaca."},{"id":"q7","question":"¿Qué estructuras filtran la linfa y atrapan patógenos?","options":[{"id":"a","text":"Los riñones","is_correct":false},{"id":"b","text":"Los ganglios linfáticos","is_correct":true},{"id":"c","text":"Los alvéolos","is_correct":false},{"id":"d","text":"Las glándulas suprarrenales","is_correct":false}],"explanation":"Los ganglios linfáticos son puntos de control llenos de células inmunes que inspeccionan la linfa en busca de invasores."},{"id":"q8","question":"¿Cuál fue la primera enfermedad humana erradicada en el mundo gracias a la vacunación?","options":[{"id":"a","text":"La viruela","is_correct":true},{"id":"b","text":"La poliomielitis","is_correct":false},{"id":"c","text":"El sarampión","is_correct":false},{"id":"d","text":"La tuberculosis","is_correct":false}],"explanation":"La OMS declaró la viruela erradicada en 1980, tras una campaña mundial de vacunación."}]'::jsonb,
  null,
  array['ciencia', 'cuerpo humano', 'sistema inmune', 'vacunas', 'salud']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

